from pathlib import Path
import hashlib,json,pandas as pd
R=Path('/Users/bytedance/Documents/Codex/2026-11-06/entry_state_selection_v1');P=R/'old_result_association_v1';D=P/'coverage_supplement_v1'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(n,o):(D/n).write_text(json.dumps(o,ensure_ascii=False,indent=2,allow_nan=False))
sources=[P/'ALL_ASSOCIATED_ROUNDS.csv',P/'FROZEN_GATE_KEYS.json',P/'OUTPUT_HASHES.json']+[R/f'price_dmi_priority_dynamic_v1/report_{y}/ALL_ROUNDS.csv' for y in [2022,2024]]
h={str(p):sha(p) for p in sources};save('INPUT_HASHES_BEFORE.json',h)
(D/'PROTOCOL.md').write_text('Coverage-only supplement. Preserve every original association artifact and its exact hashes. Use saved latest DMI report baseline (original joint) financial_covered, coverage_reason and unknown fields, joined one-to-one by original round_id with original sid/signal_day and full closed net verified. This is not the new DMI arm. Initial known_old_full means original saved closed net, NOT financially covered FULL. Relabel that semantic here; independently financial-covered known requires saved closed net, financial_covered=true and unknown=false. Closed but financial-uncovered becomes UNKNOWN for financial FULL; preserve its original conditional closed result separately, not zero. Report ALL and COMMON full denominators, fees and per-stock sums; retain all original 167 common DENY. No CORE expansion, economic runs, gate changes or strategy conclusions.\n')
x=pd.read_csv(P/'ALL_ASSOCIATED_ROUNDS.csv',low_memory=False);cov=pd.concat([pd.read_csv(p,low_memory=False) for p in sources[3:]],ignore_index=True);cov=cov[cov.arm.eq('baseline')&cov.owner_lane.eq('PRICE')]
c=['round_id','sid','signal_day','financial_covered','coverage_reason','unknown','full_closed_net'];x=x.merge(cov[c],on='round_id',how='left',suffixes=('','_coverage'),validate='one_to_one',indicator='coverage_join');assert x.coverage_join.eq('both').all();assert x.sid.eq(x.sid_coverage).all() and x.day.eq(x.signal_day_coverage).all();k=x.known_old_full;assert ((x.loc[k,'old_FULL_net']-x.loc[k,'full_closed_net']).abs()<1e-7).all()
x['original_saved_closed_net']=x.old_FULL_net;x['financial_FULL_known']=x.known_old_full & x.financial_covered & ~x.unknown;x['financial_FULL_net']=x.old_FULL_net.where(x.financial_FULL_known);x['closed_but_financial_uncovered']=x.known_old_full & ~x.financial_covered
x.to_csv(D/'ALL_ROUNDS_COVERAGE.csv',index=False);x[x.closed_but_financial_uncovered].to_csv(D/'CLOSED_BUT_FINANCIALLY_UNCOVERED.csv',index=False)
def stats(z):
 v=z.loc[z.financial_FULL_known,'financial_FULL_net'];return dict(original_registered_rounds=len(z),actual_proxy_buy=int(z.actual_buy.sum()),original_saved_closed_net_count=int(z.known_old_full.sum()),closed_but_financial_uncovered=int(z.closed_but_financial_uncovered.sum()),financial_FULL_known_count=len(v),financial_FULL_UNKNOWN_buy=int((z.actual_buy&~z.financial_FULL_known).sum()),no_buy=int((~z.actual_buy).sum()),financial_FULL_net=float(v.sum()) if len(v) else None,winners=int((v>0).sum()),losers=int((v<0).sum()),zeros=int((v==0).sum()),gross_winning_net_sum=float(v[v>0].sum()) if len(v) else None,gross_losing_net_sum=float(v[v<0].sum()) if len(v) else None,included_fees_financial_known=float(z.loc[z.financial_FULL_known,'fees'].sum()) if len(v) else None)
ss=[];stock=[]
for w,t in x.groupby('window'):
 for scope,u in [('ALL',t),('COMMON',t[t.common])]:
  for gate,z in [('TOTAL',u)]+list(u.groupby('gate_group')):
   ss.append(dict(window=w,scope=scope,gate=gate,**stats(z)))
   for sid,v in z.groupby('sid'):stock.append(dict(window=w,scope=scope,gate=gate,sid=sid,**stats(v)))
pd.DataFrame(ss).to_csv(D/'FINANCIAL_COVERAGE_SUMMARY.csv',index=False);save('FINANCIAL_COVERAGE_SUMMARY.json',ss);pd.DataFrame(stock).to_csv(D/'PER_STOCK_FINANCIAL_RESULTS.csv',index=False)
assert list(x[x.closed_but_financial_uncovered].groupby('window').size())==[30,14];assert x.loc[x.common&x.actual_buy,'financial_FULL_known'].all();assert len(x[x.common&x.actual_buy&x.gate_group.eq('DENY')])==167
assert h=={str(p):sha(p) for p in sources};original=json.loads((P/'OUTPUT_HASHES.json').read_text());assert all(sha(P/n)==v for n,v in original.items());save('QA.json',dict(original_association_files_unchanged=True,all_source_hashes_unchanged=True,exact_original_baseline_join=True,closed_uncovered_2022=30,closed_uncovered_2024=14,common167_unchanged=True,economic_runs=0));save('INPUT_HASHES_AFTER.json',h)
lines=['# Financial coverage clarification: use this supplement for ALL financially known FULL','Initial parent-directory known_old_full / known_full_buy were saved conditional closed-net fields, NOT financially covered FULL. They must not be described as audited financial FULL. No initial table has been overwritten.','The latest saved baseline report identifies 30/14 closed PRICE rounds outside financial coverage. Their saved conditional closed numbers are retained separately, but their financial FULL is UNKNOWN, not zero. COMMON167 remains unchanged.','Historical associations only; not avoided losses or strategy benefit. The opposite DENY signs in the two windows do not qualify the gate for promotion.','No new independent CORE work is claimed. The original-report CORE inventory was limited to the original economic folders, not a claim that no later report has independent diagnostics.','']
for z in ss:lines.append(str(z))
(D/'READOUT.md').write_text('\n'.join(lines)+'\n');save('OUTPUT_HASHES.json',{p.name:sha(p) for p in D.iterdir() if p.is_file() and p.name!='OUTPUT_HASHES.json'});print(pd.DataFrame(ss).to_string(index=False))
